q=Path('/mnt/c/gecko_main/openclaw/application-queue');j=sys.argv[1];p=json.loads((q/j/'application-package.json').read_text());e=json.loads((q/j/'submission-result.json').read_text());r=subprocess.run(['/home/dcall/.openclaw/bin/openclaw','browser','evaluate','--target-id','retry-'+j,'--fn','() => ({url:location.href,title:document.title,text:document.body.innerText})','--json'],capture_output=True,text=True,timeout=90);assert r.returncode==0,r.stderr;d=json.loads(r.stdout);c=d['result'];assert c['url']==p['company_application_url']+'/confirmation' and c['title']=='Thank you for applying';assert 'Your application has been received' in c['text'] or 'We have received your application' in c['text'] or (p['company']=='Eve' and 'Thanks for applying to Eve!' in c['text'] and 'Our team is reviewing applications closely' in c['text']);(q/j/'confirmation.json').write_text(json.dumps(d,indent=2));e.update(outcome='submitted',confirmation_url=c['url'],confirmation_text=c['text'],timestamp=datetime.now(ZoneInfo('America/Denver')).isoformat());e.pop('blocking_questions',None);tmp=q/j/'submission-result.tmp';tmp.write_text(json.dumps(e,indent=2));tmp.replace(q/j/'submission-result.json');print(json.dumps({'job_id':j,'outcome':'submitted','confirmation_url':c['url']}))
